 await ports.environmentMustBeAbsent(environment);api('PUT',repo+'/environments/'+environment,{deployment_branch_policy:{protected_branches:false,custom_branch_policies:true}},ports);api('POST',repo+'/environments/'+environment+'/deployment-branch-policies',{name:tag,type:'tag'},ports);await ports.verifyEnvironmentPolicy(environment,tag);ports.check();ports.verifyRemoteSourceAndTag();P.approval(a,ports.now());
