 const inputs={operation_id:a.operationId,workflow_sha:a.workflowCommit,source_review_sha:a.sourceReviewSha256,environment_name:environment,release_id:String(releaseId),input_asset_id:String(inputAsset.assetId),input_cipher_sha:inputAsset.cipherSha256,input_cipher_bytes:String(inputAsset.cipherBytes)};
 // gh run returns204 with empty output; no assumed run ID/success.
