function createCipherRelease(a,current,file,ports){P.approval(a,ports.now());P.repository(current,ports.now());if(current.refSha!==a.workflowCommit||typeof file!=='string'||!file.endsWith('/protected/'+a.operationId+'/input-'+a.operationId+'.nmae')&&!file.endsWith('\\protected\\'+a.operationId+'\\input-'+a.operationId+'.nmae'))P.fail();ports.check();ports.requireTagAndReleaseAbsent();const b=H.read(file,400*1024*1024),tag='nm-ios16-'+a.operationId,v=api('POST','/repos/'+P.REPOSITORY+'/releases',{tag_name:tag,target_commitish:a.workflowCommit,name:tag,body:'Encrypted per-operation CI input/output only. No plaintext application artifact.',draft:false,prerelease:true},ports);if(!Number.isSafeInteger(v.id)||v.id<1||v.tag_name!==tag||v.target_commitish!==a.workflowCommit)P.fail();ports.verifyRemoteSourceAndTag();P.approval(a,ports.now());cli(['release','upload',tag,file,'--repo',P.REPOSITORY],undefined,ports);const after=api('GET','/repos/'+P.REPOSITORY+'/releases/'+v.id,undefined,ports);const assets=after.assets.filter(x=>x.name==='input-'+a.operationId+'.nmae');if(assets.length!==1||assets[0].size!==b.length||assets[0].state!=='uploaded'||assets[0].digest&&assets[0].digest!=='sha256:'+H.sha(b))P.fail();ports.check();if(H.sha(H.read(file,400*1024*1024))!==H.sha(b))P.fail();return{releaseId:v.id,inputAsset:{assetId:assets[0].id,cipherSha256:H.sha(b),cipherBytes:b.length}};}
function verifyEnvironment(a,ports={}){const base='/repos/'+P.REPOSITORY+'/environments/'+a.environmentName,v=api('GET',base,undefined,ports),p=api('GET',base+'/deployment-branch-policies',undefined,ports);if(v.name!==a.environmentName||v.deployment_branch_policy?.protected_branches!==false||v.deployment_branch_policy?.custom_branch_policies!==true||p.total_count!==1||p.branch_policies?.length!==1||p.branch_policies[0].name!=='nm-ios16-'+a.operationId||p.branch_policies[0].type!=='tag')P.fail();return true;}
